with-actions.code:
import { ListBuilder } from '/vendor/ssi-builders/src/index.js';
import { IconManager } from '/vendor/ssi-builders/src/index.js';

IconManager.setPreset('lucide');

new ListBuilder({
    containerId: 'my-list',
    columns: [
        { key: 'name', label: 'Name' },
        { key: 'email', label: 'Email' }
    ],
    actions: [
        {
            label: 'Edit',
            icon: IconManager.getIcon('edit'),
            handler: (row) => console.log('Edit', row)
        },
        {
            label: 'Delete',
            icon: IconManager.getIcon('delete'),
            handler: (row) => console.log('Delete', row),
            variant: 'danger'
        }
    ],
    dataSource: async () => {
        const response = await fetch('/api/users');
        return response.json();
    }
});

basic.code:
import { FormBuilder } from '/vendor/ssi-builders/src/index.js';

const form = new FormBuilder({
    containerId: 'my-form',
    fields: [
        {
            name: 'name',
            label: 'Full Name',
            type: 'text',
            required: true,
            placeholder: 'Enter your name'
        },
        {
            name: 'email',
            label: 'Email',
            type: 'email',
            required: true,
            validation: {
                pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
                message: 'Please enter a valid email'
            }
        },
        {
            name: 'message',
            label: 'Message',
            type: 'textarea',
            rows: 4
        }
    ],
    onSubmit: async (data) => {
        const response = await fetch('/api/contact', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data)
        });
        return response.json();
    }
});

form.render();

modal-form.code:
import { ModalBuilder } from '/vendor/ssi-builders/src/index.js';

const userData = await ModalBuilder.form({
    title: 'Edit User',
    size: 'medium',
    fields: [
        { name: 'name', label: 'Name', type: 'text', required: true },
        { name: 'email', label: 'Email', type: 'email', required: true },
        { name: 'role', label: 'Role', type: 'select', options: [
            { value: 'admin', label: 'Admin' },
            { value: 'user', label: 'User' }
        ]}
    ],
    values: { name: 'John', email: 'john@example.com', role: 'user' },
    submitLabel: 'Save Changes'
});

if (userData) {
    await fetch('/api/users/1', {
        method: 'PUT',
        body: JSON.stringify(userData)
    });
}

