import { MessageBuilder } from '/vendor/ssi-builders/src/index.js';

new MessageBuilder({
    containerId: 'alerts',
    type: 'warning',
    title: 'Session Expiring',
    message: 'Your session will expire in 5 minutes.',
    dismissible: true,
    actions: [
        {
            label: 'Extend Session',
            handler: async (msg) => {
                await fetch('/api/extend-session', { method: 'POST' });
                msg.dismiss();
            },
            variant: 'filled'
        },
        {
            label: 'Logout',
            handler: () => window.location.href = '/logout'
        }
    ]
});
